import UIKit
import XCTest
@testable import TransportCat

/// S8: every image name the UI builds from a line (`train-`, `badge-`,
/// `station-`, `terminal-`) plus the fixed tab and status icons must exist in
/// the app asset catalog. The catalog is generated by `scripts/render-assets.sh`
/// from `statics/`, so a missing name means the script was not re-run or a line
/// was added without its assets.
///
/// The bus pictograms (icons-v2 S2, S3, S4) are covered by the same rule: one
/// `bus-<colorHex>` imageset per line colour, `bus-default` as the fallback.
final class AssetCatalogTests: XCTestCase {
    /// The asset catalog is compiled into the app bundle, which is where
    /// `AppModel` lives; the test bundle itself has no images.
    private let bundle = Bundle(for: AppModel.self)

    private func assertImageExists(
        _ name: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertNotNil(
            UIImage(named: name, in: bundle, compatibleWith: nil),
            "asset catalog is missing image '\(name)' (run scripts/render-assets.sh)",
            file: file,
            line: line
        )
    }

    func testTrainBadgeStationAndTerminalAssetsExistForEveryLine() {
        for line in MetroLine.allLines {
            let key = line.displayName.lowercased()
            XCTAssertEqual(key, line.assetKey, "assetKey must stay the lowercased display name")
            assertImageExists("train-\(key)")
            assertImageExists("badge-\(key)")
            assertImageExists("station-\(key)")
            assertImageExists("terminal-\(key)")
        }
    }

    func testTabAndStatusIconsExist() {
        for name in [
            "tab-map", "tab-network", "tab-alert",
            "icon-accessible", "icon-alert",
            "icon-escalator", "icon-elevator", "icon-entrance",
            "icon-realtime-off",
        ] {
            assertImageExists(name)
        }
    }

    /// S2, S4: the bus pictograms are the standard silhouette re-tinted to each
    /// of the eight `COLOR_LINIA` values the TMB bus catalog publishes, plus the
    /// blue `bus-default` the fallback (S3) uses. A missing name means
    /// `scripts/render-assets.sh` was not re-run after the set was added.
    func testBusMarkerAssetsExistForEveryLineColor() {
        for hex in [
            "003888", "6ab023", "937500", "da291c",
            "93107e", "010101", "df2228", "076ab3",
        ] {
            assertImageExists("bus-\(hex)")
        }
        assertImageExists("bus-default")
    }

    /// S1, S4: the v2 train art is 216x96 px, which `UIImage.size` reports in
    /// points (72x32 pt at 3x). A different size means the imageset came from
    /// the old `map-trains/` set instead of `map-trains-v2/`.
    func testTrainImagesAreTheV2Size() {
        for line in MetroLine.allLines {
            let name = "train-\(line.displayName.lowercased())"
            guard let image = UIImage(named: name, in: bundle, compatibleWith: nil) else {
                XCTFail("asset catalog is missing image '\(name)'")
                continue
            }
            XCTAssertEqual(image.scale, 3, "\(name) must ship as a @3x image")
            XCTAssertEqual(image.size.width * image.scale, 216, accuracy: 1, "\(name) width")
            XCTAssertEqual(image.size.height * image.scale, 96, accuracy: 1, "\(name) height")
        }
    }

    /// S3: an asset name is the line colour lowercased, and a colour with no
    /// imageset of its own falls back to `bus-default` instead of naming an
    /// image that does not exist.
    func testBusAssetNameUsesLineColorOrFallback() {
        func line(colorHex: String) -> BusLine {
            BusLine(
                code: 212,
                name: "H12",
                description: "Trinitat Nova - Zona Universitaria",
                origin: "Trinitat Nova",
                destination: "Zona Universitaria",
                colorHex: colorHex,
                textColorHex: "FFFFFF",
                familyCode: 5,
                familyName: "Horitzontals",
                familyOrder: 2,
                order: 3
            )
        }
        XCTAssertEqual(BusMarker.assetName(for: line(colorHex: "6AB023")), "bus-6ab023")
        XCTAssertEqual(BusMarker.assetName(for: line(colorHex: "003888")), "bus-003888")
        // CE1126 is a catalog colour with no imageset generated for it.
        XCTAssertEqual(BusMarker.assetName(for: line(colorHex: "CE1126")), "bus-default")
    }
}
